DO $$ DECLARE v_def text; BEGIN SELECT pg_get_functiondef('platform_private.storage1_consultor_core(text,text)'::regprocedure) INTO v_def; IF position('OR p_action IS NULL' IN v_def)=0 THEN v_def:=replace(v_def,'IF auth.uid() IS NULL OR NOT public.storage1_path_strict(p_name)','IF auth.uid() IS NULL OR p_action IS NULL OR NOT public.storage1_path_strict(p_name)'); EXECUTE v_def; END IF; END; $$;